#include <assert.h>
#include <math.h>
#include <stdio.h>

#include <gkyl_gyrokinetic_priv.h>

static void
mapc2p(double t, const double *zc, double *xp, void *ctx)
{
  for (int d = 0; d < 3; ++d) {
    xp[d] = zc[d];
  }
}

static void
bfield(double t, const double *zc, double *out, void *ctx)
{
  out[0] = out[1] = 0.0;
  out[2] = 1.0;
}

static void
initial_distribution(double t, const double *xn, double *out, void *ctx)
{
  out[0] = exp(-0.5 * (xn[1] - 0.3) * (xn[1] - 0.3) - xn[2]);
}

static void
check_filter(bool cellwise_const)
{
  struct gkyl_gk inp = {
    .name = "rt_gk_fbardot_1x2v_p1",
    .cdim = 1,
    .lower = {0.0},
    .upper = {1.0},
    .cells = {2},
    .poly_order = 1,
    .basis_type = GKYL_BASIS_MODAL_SERENDIPITY,
    .geometry = {.geometry_id = GKYL_GEOMETRY_MAPC2P, .mapc2p = mapc2p, .bfield_func = bfield},
    .num_periodic_dir = 1,
    .periodic_dirs = {0},
    .num_species = 1,
    .species = {{
      .name = "test",
      .charge = 1.0,
      .mass = 1.0,
      .vdim = 2,
      .lower = {-4.0, 0.0},
      .upper = {4.0, 4.0},
      .cells = {8, 4},
      .polarization_density = 1.0,
      .projection = {.proj_id = GKYL_PROJ_FUNC, .func = initial_distribution},
      .time_rate_diagnostics = true,
      .damping = {.type = GKYL_GK_DAMPING_LOW_PASS_FILTER, .rate_const = 2.0,
        .cellwise_const = cellwise_const},
    }},
    .field = {.gkfield_id = GKYL_GK_FIELD_BOLTZMANN, .electron_mass = 1.0,
      .electron_charge = -1.0, .electron_temp = 1.0, .zero_init_field = true, .is_static = true},
  };
  struct gkyl_gyrokinetic_app *app = gkyl_gyrokinetic_app_new(&inp);
  gkyl_gyrokinetic_app_apply_ic(app, 0.0);
  struct gk_species *gks = &app->species[0];
  int num_mom = gks->integ_moms.num_mom;
  struct gkyl_array *delta = gkyl_array_new(GKYL_DOUBLE, gks->basis.num_basis, gks->f->size);
  struct gkyl_array *old = gkyl_array_new(GKYL_DOUBLE, gks->damping.fbar->ncomp, gks->f->size);

  // Start away from filter equilibrium so the time-rate diagnostic is nonzero.
  gkyl_array_scale(gks->damping.fbar, 0.5);
  double tm = 0.0;
  for (int step = 0; step < 2; ++step) {
    gkyl_array_copy(old, gks->damping.fbar);
    struct gkyl_update_status status = gkyl_gyrokinetic_update(app, 0.01);
    assert(status.success);
    tm += status.dt_actual;

    // Independently integrate the distribution difference across the accepted step.
    gkyl_array_clear(delta, 0.0);
    gkyl_array_set_offset(delta, 1.0 / status.dt_actual, gks->damping.fbar, 0);
    gkyl_array_accumulate_offset(delta, -1.0 / status.dt_actual, old, 0);
    gk_species_moment_calc(&gks->integ_moms, gks->local, app->local, delta);
    double expected[num_mom], actual[num_mom], fdot[num_mom];
    gkyl_array_reduce_range(expected, gks->integ_moms.marr, GKYL_SUM, &app->local);
    assert(fabs(expected[0]) > 1.0e-6);

    // Repeated diagnostic calls must not subtract the old state twice.
    for (int repeat = 0; repeat < 2; ++repeat) {
      gkyl_gyrokinetic_app_calc_integrated_mom(app, tm);
      assert(gkyl_dynvec_getlast(gks->fbardot_integ_diag, actual));
      assert(gkyl_dynvec_getlast(gks->fdot_integ_diag, fdot));
      for (int m = 0; m < num_mom; ++m) {
        assert(fabs(actual[m] - expected[m]) < 1.0e-10 * fmax(1.0, fabs(expected[m])));
        if (!cellwise_const || m == 0) {
          assert(fabs(actual[m] + fdot[m]) < 1.0e-10 * fmax(1.0, fabs(expected[m])));
        }
      }
    }
    // Exercise creation and subsequent append of the diagnostic file.
    gkyl_gyrokinetic_app_write_integrated_mom(app);
  }
  gkyl_dynvec saved = gkyl_dynvec_new(GKYL_DOUBLE, num_mom);
  assert(gkyl_dynvec_read(saved, "rt_gk_fbardot_1x2v_p1-test_fbardot_integrated_moms.gkyl"));
  assert(gkyl_dynvec_size(saved) == 4);
  assert(gkyl_dynvec_getlast_tm(saved) == tm);
  gkyl_dynvec_release(saved);
  gkyl_array_release(old);
  gkyl_array_release(delta);
  gkyl_gyrokinetic_app_release(app);
  printf("fbardot %s: passed\n", cellwise_const ? "p0" : "species basis");
}

int
main(int argc, char **argv)
{
  check_filter(false);
  check_filter(true);
  return 0;
}
